/**
 * JJK5e technique audio-visuals: one cast sound per technique, an impact sound per family, module events
 * (domain, clash, Black Flash, The Zone, burnout), ink effects tinted per technique, and domain backdrops.
 *
 * Everything listens to documents that every client receives (chat cards, actor flags, active effects, regions),
 * so each player hears the sound once, at their own volume, with no socket traffic. Visuals are played by the
 * author only, because Sequencer already shares them with the table.
 * All media under sounds/, effects/ and textures/ is generated by tools/build-fx.py (no third-party assets).
 */
import { FX_TABLE } from "./jjk-fx-table.mjs";

const ID = "jjk5e";
const ROOT = `modules/${ID}`;
const L = (en, es) => (game.i18n?.lang?.startsWith?.("es") ? es : en);
const setting = (key, fallback = null) => { try { return game.settings.get(ID, key); } catch { return fallback; } };

/* ------------------------------------------------------------------ lookups (pure, tested) */
export function techniqueOf(item) {
  const name = item?.flags?.[ID]?.technique;
  return name && FX_TABLE.techniques[name] ? name : null;
}
/** Family of an item (from the identity seals when available, else "ce"). */
export function familyOf(item) {
  try { return game.modules.get(ID)?.api?.familyOf?.(item) ?? "ce"; } catch { return "ce"; }
}
/** Everything the table knows about an item: colour, shape, cast sound, impact sound, backdrop. */
export function fxFor(item) {
  const tech = techniqueOf(item);
  const fam = familyOf(item);
  const entry = tech ? FX_TABLE.techniques[tech] : null;
  const impactFamily = FX_TABLE.familyImpact.includes(fam) ? fam : "ce";
  return {
    technique: tech,
    color: entry?.color ?? null,
    shape: entry?.shape ?? FX_TABLE.familyShape[fam] ?? "burst",
    cast: entry ? `${ROOT}/sounds/techniques/${entry.sound}.ogg` : null,
    impact: `${ROOT}/sounds/impact/${impactFamily}.ogg`,
    backdrop: entry?.backdrop ?? "void"
  };
}
export const eventSound = (name) => (FX_TABLE.events.includes(name) ? `${ROOT}/sounds/events/${name}.ogg` : null);
export const effectFile = (shape) => `${ROOT}/effects/${FX_TABLE.shapes.includes(shape) ? shape : "burst"}.webm`;
export const backdropFile = (name) => `${ROOT}/textures/domains/${FX_TABLE.backdrops.includes(name) ? name : "void"}.webp`;

/* ------------------------------------------------------------------ sound */
const recent = new Map();
let playing = 0;
/** Plays a sound on this client only. Repeats of the same file within 150 ms and more than 4 at once are dropped. */
export function playSound(src, { volume = 1, now = Date.now() } = {}) {
  if (!src || !setting("sfxEnabled", true)) return false;
  const vol = Math.max(0, Math.min(1, Number(setting("sfxVolume", 0.7)) * volume));
  if (vol <= 0) return false;
  if (now - (recent.get(src) ?? -Infinity) < 150 || playing >= 4) return false;
  recent.set(src, now);
  const helper = globalThis.foundry?.audio?.AudioHelper ?? globalThis.AudioHelper;
  if (!helper?.play) return false;
  playing++;
  Promise.resolve(helper.play({ src, volume: vol, autoplay: true, loop: false, channel: "interface" }, false))
    .then((sound) => { if (sound?.addEventListener) sound.addEventListener("end", () => { playing = Math.max(0, playing - 1); }, { once: true }); else setTimeout(() => { playing = Math.max(0, playing - 1); }, 1500); })
    .catch(() => { playing = Math.max(0, playing - 1); });
  return true;
}

/* ------------------------------------------------------------------ visuals */
const sequencerOn = () => !!(game.modules.get("sequencer")?.active && typeof globalThis.Sequence === "function");
const jb2aOn = () => !!(game.modules.get("JB2A_DnD5e")?.active || game.modules.get("jb2a_patreon")?.active);
/** "auto": our sigil on every cast + our impacts when JB2A is missing; "own": only ours; "off": none of ours. */
export function visualMode() { return setting("techniqueFX", "auto"); }
export const ownImpacts = () => visualMode() === "own" || (visualMode() === "auto" && !jb2aOn());

function reducedMotion() {
  try { return globalThis.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches === true; } catch { return false; }
}

function play(shape, at, { color = null, scale = 1.5, below = false, size = null } = {}) {
  if (!sequencerOn() || !at || visualMode() === "off" || !setting("animations", true)) return false;
  try {
    const seq = new globalThis.Sequence();
    const eff = seq.effect().file(effectFile(shape)).atLocation(at);
    if (size) eff.size(size, { gridUnits: true }); else eff.scaleToObject(scale);
    if (color) eff.tint(color);
    if (below) eff.belowTokens();
    eff.fadeIn(80).fadeOut(240);
    if (reducedMotion()) eff.playbackRate?.(0.75);
    seq.play();
    return true;
  } catch (err) { console.warn(`${ID} | effect`, err); return false; }
}

/* ------------------------------------------------------------------ chat cards → cast / hit */
function cardItem(message) {
  const uuid = message?.flags?.dnd5e?.item?.uuid;
  if (!uuid) return null;
  try { return globalThis.fromUuidSync?.(uuid) ?? null; } catch { return null; }
}
function cardTargets(message) {
  return [...(message?.flags?.dnd5e?.targets ?? [])].map((t) => {
    try { const doc = globalThis.fromUuidSync?.(t.uuid); return { ac: Number(t.ac), token: doc?.object ?? doc?.getActiveTokens?.()?.[0] ?? null }; }
    catch { return { ac: Number(t.ac), token: null }; }
  });
}
function speakerToken(message, item) {
  const id = message?.speaker?.token;
  return (id && globalThis.canvas?.tokens?.get?.(id)) || item?.actor?.getActiveTokens?.()?.[0] || null;
}

/** What a JJK chat card means for the sound and the picture (pure, tested). */
export function readCard(message) {
  const d5 = message?.flags?.dnd5e ?? {};
  const kind = d5.messageType === "usage" ? "cast" : d5.messageType === "roll" && d5.roll?.type === "attack" ? "attack"
    : d5.messageType === "roll" && d5.roll?.type === "damage" ? "damage" : null;
  if (!kind) return null;
  const item = cardItem(message);
  if (!item?.flags?.[ID] || item.flags[ID].cePool) return null;
  return { kind, item, fx: fxFor(item) };
}

function onChatMessage(message) {
  if (message?.visible === false) return;           // a blind or private roll stays silent for whoever cannot see it
  const card = readCard(message);
  if (!card) return;
  const { kind, item, fx } = card;
  const mine = message.isAuthor ?? message.author?.id === game.user?.id;
  if (kind === "cast") {
    if (fx.cast) playSound(fx.cast);
    if (!mine || !fx.technique) return;
    const source = speakerToken(message, item);
    play("sigil", source, { color: fx.color, scale: 1.9, below: true });
    if (ownImpacts()) {
      const targets = cardTargets(message).map((t) => t.token).filter(Boolean);
      setTimeout(() => { for (const tk of targets) play(fx.shape, tk, { color: fx.color, scale: 1.6 }); }, 380);
    }
    return;
  }
  if (kind === "attack") {
    const total = Number(message.rolls?.[0]?.total);
    const crit = !!message.rolls?.[0]?.isCritical;
    const targets = cardTargets(message);
    const hits = targets.filter((t) => crit || !Number.isFinite(t.ac) || !Number.isFinite(total) || total >= t.ac);
    if (hits.length || !targets.length) setTimeout(() => playSound(fx.impact, { volume: 0.9 }), 250);
    if (mine && ownImpacts()) for (const t of hits) if (t.token) play(fx.shape, t.token, { color: fx.color ?? null, scale: 1.4 });
  }
}

/* ------------------------------------------------------------------ module events from documents */
function onActorUpdate(actor, changes) {
  const flags = changes?.flags?.[ID];
  if (!flags) return;
  if (flags.pendingBlackFlash === true) playSound(eventSound("black-flash"));
  if ("domainState" in flags || "-=domainState" in flags) {
    const before = domainMemory.get(actor.uuid) ?? null;
    const now = actor.getFlag?.(ID, "domainState") ?? null;
    domainMemory.set(actor.uuid, now ? { open: !!now.open, openingId: now.openingId, clash: !!(now.clash && !now.clash.resolved) } : null);
    if (now?.open && now.openingId && now.openingId !== before?.openingId) playSound(eventSound("domain-open"), { volume: 1 });
    else if (before?.open && !now?.open) playSound(eventSound("domain-close"));
    if (now?.open && now.clash && !now.clash.resolved && !before?.clash) playSound(eventSound("domain-clash"));
  }
}
const domainMemory = new Map();

function onEffectCreated(effect) {
  const kind = effect?.flags?.[ID]?.kind;
  if (kind === "zone" || effect?.flags?.[ID]?.zone) playSound(eventSound("zone"));
  else if (kind === "burnout" || effect?.flags?.[ID]?.burnout) playSound(eventSound("burnout"));
  else if (kind === "maxOutputActive") playSound(eventSound("max-output"));
}

/* ------------------------------------------------------------------ domain backdrops (GM writes, everyone sees) */
const isActiveGM = () => !!game.user?.isGM && (game.users?.activeGM ? game.users.activeGM.id === game.user.id : true);

/** Drawing data that fills a domain Region's shape with the backdrop texture (pure, tested). */
export function backdropDrawing(region, texture) {
  const shape = region?.shapes?.[0];
  if (!shape) return null;
  let x, y, w, h, s;
  if (shape.type === "polygon") {
    const xs = shape.points.filter((_, i) => i % 2 === 0), ys = shape.points.filter((_, i) => i % 2 === 1);
    x = Math.min(...xs); y = Math.min(...ys); w = Math.max(...xs) - x; h = Math.max(...ys) - y;
    s = { type: "p", width: w, height: h, points: shape.points.map((v, i) => v - (i % 2 === 0 ? x : y)) };
  } else {
    const rx = shape.radiusX ?? shape.radius, ry = shape.radiusY ?? shape.radius;
    if (![shape.x, shape.y, rx, ry].every(Number.isFinite)) return null;
    x = shape.x - rx; y = shape.y - ry; w = rx * 2; h = ry * 2;
    s = { type: "e", width: w, height: h };
  }
  return {
    x, y, shape: s, texture, fillType: globalThis.CONST?.DRAWING_FILL_TYPES?.PATTERN ?? 2, fillColor: "#ffffff", fillAlpha: 0.86,
    strokeWidth: 6, strokeColor: "#0d0a0e", strokeAlpha: 0.85, locked: true, hidden: false,
    elevation: Number.isFinite(region.elevation?.bottom) ? region.elevation.bottom : 0, sort: -1000,
    flags: { [ID]: { domainBackdrop: region.id, domain: region.flags?.[ID]?.domain, openingId: region.flags?.[ID]?.openingId } }
  };
}

function backdropFor(region) {
  const actorUuid = region?.flags?.[ID]?.domain;
  let actor = null;
  try { actor = actorUuid ? globalThis.fromUuidSync?.(actorUuid) : null; } catch { /* */ }
  const chosen = actor?.getFlag?.(ID, "domainBackdrop");
  if (chosen === "none") return null;
  if (chosen && FX_TABLE.backdrops.includes(chosen)) return chosen;
  const tech = actor?.getFlag?.(ID, "technique") ?? actor?.items?.find?.((i) => i.flags?.[ID]?.technique)?.flags?.[ID]?.technique;
  return FX_TABLE.techniques[tech]?.backdrop ?? "void";
}

const ownBackdrops = (scene, regionId) => [...(scene?.drawings ?? [])].filter((d) => d.flags?.[ID]?.domainBackdrop && (!regionId || d.flags[ID].domainBackdrop === regionId));

async function syncBackdrop(region, deleted = false) {
  if (!isActiveGM() || !region?.flags?.[ID]?.domain || region.flags[ID].clashZone) return;
  const scene = region.parent;
  const existing = ownBackdrops(scene, region.id);
  const name = !deleted && setting("domainBackdrops", true) ? backdropFor(region) : null;
  const data = name ? backdropDrawing(region, backdropFile(name)) : null;
  try {
    if (!data) { if (existing.length) await scene.deleteEmbeddedDocuments("Drawing", existing.map((d) => d.id)); return; }
    if (existing.length) {
      await scene.updateEmbeddedDocuments("Drawing", [{ _id: existing[0].id, ...data }]);
      if (existing.length > 1) await scene.deleteEmbeddedDocuments("Drawing", existing.slice(1).map((d) => d.id));
    } else await scene.createEmbeddedDocuments("Drawing", [data]);
  } catch (err) { console.warn(`${ID} | domain backdrop`, err); }
}

/** Drawings left behind by a lost close (their Region is gone): removed at ready and by the domain cleanup. */
export async function sweepBackdrops(scenes = game.scenes ?? []) {
  if (!isActiveGM()) return 0;
  let n = 0;
  for (const scene of scenes) {
    const orphans = ownBackdrops(scene).filter((d) => !scene.regions?.get?.(d.flags[ID].domainBackdrop));
    if (!orphans.length) continue;
    try { await scene.deleteEmbeddedDocuments("Drawing", orphans.map((d) => d.id)); n += orphans.length; } catch { /* */ }
  }
  return n;
}

/* ------------------------------------------------------------------ backdrop picker (panel button) */
const BACKDROP_NAMES = {
  void: ["Void", "Vacío"], shrine: ["Shrine", "Santuario"], abyss: ["Abyss", "Abismo"], sea: ["Sea", "Mar"], garden: ["Garden", "Jardín"],
  volcano: ["Volcano", "Volcán"], storm: ["Storm", "Tormenta"], ink: ["Ink", "Tinta"], mirror: ["Mirrors", "Espejos"],
  temple: ["Temple", "Templo"], ice: ["Ice", "Hielo"], circuit: ["Circuit", "Circuito"]
};
export async function chooseBackdrop(actor) {
  if (!actor?.isOwner) return null;
  const current = actor.getFlag(ID, "domainBackdrop") ?? "";
  const auto = (() => { const tech = actor.getFlag(ID, "technique"); return FX_TABLE.techniques[tech]?.backdrop ?? "void"; })();
  const tile = (value, label, src) => `<label class="jjk-backdrop-choice">
      <input type="radio" name="backdrop" value="${value}" ${current === value ? "checked" : ""}>
      ${src ? `<img src="${src}" alt="" loading="lazy">` : `<span class="jjk-backdrop-none" aria-hidden="true"><i class="fas fa-ban"></i></span>`}
      <span>${label}</span></label>`;
  const content = `<p class="hint">${L("The pattern fills your barrier while the domain is open. Tokens stay on top.", "El patrón rellena tu barrera mientras el dominio está abierto. Las fichas quedan encima.")}</p>
    <div class="jjk-backdrop-grid">
      ${tile("", L(`Automatic (${BACKDROP_NAMES[auto][0]})`, `Automático (${BACKDROP_NAMES[auto][1]})`), backdropFile(auto))}
      ${FX_TABLE.backdrops.map((b) => tile(b, L(...BACKDROP_NAMES[b]), backdropFile(b))).join("")}
      ${tile("none", L("No backdrop", "Sin fondo"), null)}
    </div>`;
  const value = await foundry.applications.api.DialogV2.prompt({
    classes: ["jjk5e-ui", "jjk5e-dialog", "jjk-backdrop-dialog"], window: { resizable: true, title: L("Domain backdrop", "Fondo de dominio") },
    position: { width: 640 }, rejectClose: false, content,
    ok: { label: L("Save", "Guardar"), callback: (e, b) => b.form.elements.backdrop.value ?? "" }
  });
  if (value === null || value === undefined) return null;
  if (value) await actor.setFlag(ID, "domainBackdrop", value); else await actor.unsetFlag(ID, "domainBackdrop");
  return value;
}

/* ------------------------------------------------------------------ wiring */
Hooks.once("init", () => {
  const reg = (key, data) => game.settings.register(ID, key, { config: true, ...data });
  reg("sfxEnabled", { scope: "client", type: Boolean, default: true,
    name: L("Technique sounds", "Sonidos de técnicas"),
    hint: L("Plays the module's own sound for each technique, hit, domain, clash and Black Flash.", "Reproduce el sonido propio del módulo para cada técnica, impacto, dominio, choque y Black Flash.") });
  reg("sfxVolume", { scope: "client", type: Number, default: 0.7, range: { min: 0, max: 1, step: 0.05 },
    name: L("Technique sound volume", "Volumen de los sonidos de técnicas"),
    hint: L("Multiplied by Foundry's interface volume.", "Se multiplica por el volumen de interfaz de Foundry.") });
  reg("techniqueFX", { scope: "client", type: String, default: "auto",
    choices: { auto: L("Seal on every cast, own impacts without JB2A", "Sello en cada uso, impactos propios sin JB2A"),
      own: L("Only the module's ink effects", "Solo los efectos de tinta del módulo"), off: L("Off", "Desactivados") },
    name: L("Technique effects", "Efectos de técnicas"),
    hint: L("Ink effects tinted with each technique's colour (needs Sequencer).", "Efectos de tinta con el color de cada técnica (necesita Sequencer).") });
  reg("domainBackdrops", { scope: "world", type: Boolean, default: true,
    name: L("Domain backdrops", "Fondos de dominio"),
    hint: L("Fills an open domain's barrier with its technique's backdrop. Each owner can change it from the JJK panel.", "Rellena la barrera de un dominio abierto con el fondo de su técnica. Cada dueño puede cambiarlo desde el panel JJK.") });
});

Hooks.once("ready", () => {
  if (game.system?.id !== "dnd5e") return;
  const api = game.modules.get(ID)?.api;
  if (api) api.fx = { fxFor, playSound, eventSound, chooseBackdrop, sweepBackdrops, ownImpacts, visualMode, table: FX_TABLE };
  for (const actor of game.actors ?? []) {
    const s = actor.getFlag?.(ID, "domainState");
    if (s) domainMemory.set(actor.uuid, { open: !!s.open, openingId: s.openingId, clash: !!(s.clash && !s.clash.resolved) });
  }
  Hooks.on("createChatMessage", (message) => { try { onChatMessage(message); } catch (err) { console.warn(`${ID} | fx`, err); } });
  Hooks.on("updateActor", (actor, changes) => { try { onActorUpdate(actor, changes); } catch (err) { console.warn(`${ID} | fx`, err); } });
  Hooks.on("createActiveEffect", (effect) => { try { onEffectCreated(effect); } catch (err) { console.warn(`${ID} | fx`, err); } });
  Hooks.on("createRegion", (region) => syncBackdrop(region));
  Hooks.on("updateRegion", (region, changes) => { if ("shapes" in (changes ?? {})) syncBackdrop(region); });
  Hooks.on("deleteRegion", (region) => syncBackdrop(region, true));
  Hooks.on("updateActor", (actor, changes) => {
    if (!isActiveGM() || !foundry.utils.hasProperty(changes ?? {}, `flags.${ID}`) || !("domainBackdrop" in (changes.flags[ID] ?? {}) || "-=domainBackdrop" in (changes.flags[ID] ?? {}))) return;
    for (const scene of game.scenes ?? []) for (const region of scene.regions ?? []) if (region.flags?.[ID]?.domain === actor.uuid) syncBackdrop(region);
  });
  if (isActiveGM()) setTimeout(() => sweepBackdrops().catch(() => null), 2500);
});
